function hungerStrainUpgrades() {
  const out = [];
  for (const st of HUNGER_STRAINS_GH) {
    for (const unitId of st.units) {
      out.push({ unitId, upgrade: Object.assign({}, st.up, { perModelGroup:'hunger-strain',
        perModelMax: HUNGER_RAVENOUS_GH.includes(unitId) ? 3 : 1 }) });
    }
  }
  return out;
}
